'use client';
import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useSeconds } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { Spin, Swap, SwapIcon, Tip, useGrow } from '../lib/motion';
import { focusMenu, menuStep } from '../lib/popover';
import '../designme.css';
// its menus' rows glide in Clean
import '../lib/glide';
import './composer.css';

export interface ComposerAttachment {
  key: string;
  label: string;
  /** Defaults to a paper clip */
  icon?: IconName;
  /** loading shows a spinner and holds Send until it's ready; error shows the chip in red with a Try again button */
  status?: 'loading' | 'error' | 'ready';
}
export interface ComposerOption {
  value: string;
  /** Defaults to the value */
  label?: string;
  /** The quiet line under the label */
  detail?: string;
  icon?: IconName;
}

export interface ComposerProps {
  /** The text in the box. Leave it out to let the composer keep it */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  /** Called with the message when the person sends it. The box clears itself afterwards */
  onSubmit?: (message: { text: string; attachments: ComposerAttachment[] }) => void;
  /** The agent is answering: send turns into stop */
  busy?: boolean;
  /** Called by the stop button while busy */
  onStop?: () => void;
  /** The conversation above the box, like the bubbles a message turns into */
  thread?: ReactNode;

  /** Files and frames added to the message, shown as chips above the text */
  attachments?: ComposerAttachment[];
  defaultAttachments?: ComposerAttachment[];
  onAttachmentsChange?: (attachments: ComposerAttachment[]) => void;
  /** What the attach menu offers. Defaults to a file, a Figma frame and a screenshot */
  addOptions?: ComposerOption[];
  /** Called with the option's value when the person picks one from the attach menu */
  onAdd?: (value: string) => void;
  /** Called by Try again on an attachment that failed to load */
  onRetry?: (key: string) => void;

  /** What the agent can work on, like Figma files and repositories. The chip only shows when there are some */
  contexts?: ComposerOption[];
  context?: string;
  defaultContext?: string;
  onContextChange?: (context: string) => void;
  /** What the agent may do. Defaults to Ask, Edit and Plan */
  modes?: ComposerOption[];
  mode?: string;
  defaultMode?: string;
  onModeChange?: (mode: string) => void;
  /** More in the toolbar, before the mode, like a context ring */
  tools?: ReactNode;

  /** Called by the microphone button. Start listening and set dictating; the mic button only shows when this is set */
  onDictate?: () => void;
  /** Swaps the toolbar for a red dot, a clock, Cancel and Done. Write what you hear into value while it is on */
  dictating?: boolean;
  /** Seconds to show while dictating. Leave it out to let it count */
  dictationSeconds?: number;
  /** Called by Cancel (false, the text goes back to what it was) or Done (true, the text stays) */
  onDictationEnd?: (keep: boolean) => void;
  className?: string;
}

const ADD: ComposerOption[] = [
  { value: 'file', label: 'Upload a file', detail: 'Images, PDFs or code', icon: 'file-text' },
  { value: 'figma', label: 'Link a Figma frame', detail: 'From any file you can open', icon: 'figma' },
  { value: 'shot', label: 'Add a screenshot', detail: "Of the window you're in", icon: 'image' }
];
const MODES: ComposerOption[] = [
  { value: 'ask', label: 'Ask', detail: 'Answer only, change nothing', icon: 'eye' },
  { value: 'edit', label: 'Edit', detail: 'Change frames on a new page', icon: 'edit' },
  { value: 'plan', label: 'Plan', detail: 'Propose steps before it starts', icon: 'list' }
];
const PLACEHOLDER = 'Ask the design agent, or attach a frame';

type PopName = 'plus' | 'ctx' | 'mode';
const Check = () => <span className="dm-ck"><Icon name="check" /></span>;
const clock = (s: number) => Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0');

/** The message box: text that grows as you type, attachments that load, what the agent works on, what it may do, dictation and send. */
export function Composer({
  value, defaultValue = '', onValueChange, placeholder = PLACEHOLDER, onSubmit, busy = false, onStop, thread,
  attachments, defaultAttachments = [], onAttachmentsChange, addOptions = ADD, onAdd, onRetry,
  contexts, context, defaultContext, onContextChange, modes = MODES, mode, defaultMode, onModeChange, tools,
  onDictate, dictating = false, dictationSeconds, onDictationEnd, className
}: ComposerProps) {
  const [text, setText] = useControllable(value, defaultValue, onValueChange);
  const [files, setFiles] = useControllable(attachments, defaultAttachments, onAttachmentsChange);
  const [ctx, setCtx] = useControllable(context, defaultContext ?? contexts?.[0]?.value ?? '', onContextChange);
  const [md, setMd] = useControllable(mode, defaultMode ?? modes[0]?.value ?? '', onModeChange);
  const ctxOpt = contexts?.find(o => o.value === ctx), mdOpt = modes.find(o => o.value === md) ?? modes[0];
  const counted = useSeconds(dictating && dictationSeconds === undefined);

  const box = useRef<HTMLDivElement>(null), ta = useRef<HTMLTextAreaElement>(null);
  // no room is kept for the conversation (owner, 18 Nov): the thread and the box grow and shrink together, eased (as grow()
  // on the site)
  const [root, inner] = useGrow();
  // the text box grows with its text, up to 160px
  useIsoLayoutEffect(() => { const t = ta.current; if (!t) return; t.style.height = 'auto'; t.style.height = Math.min(t.scrollHeight, 160) + 'px'; }, [text, dictating]);

  /* ---------- menus: open over the composer from their button, down when there is room and up when there isn't, and close
     on a click outside, Escape or a pick. The composer never moves for them ---------- */
  const [pop, setPop] = useState<PopName | null>(null);
  const [place, setPlace] = useState<Partial<Record<PopName, CSSProperties>>>({});
  const triggers = useRef<Partial<Record<PopName, HTMLButtonElement | null>>>({});
  const pops = useRef<Partial<Record<PopName, HTMLDivElement | null>>>({});
  const pick = (fn: () => void) => () => { fn(); setTimeout(() => setPop(null), 120); };
  // the keyboard: Enter, Space or the down arrow opens a menu on its picked or first item (the up arrow, on its last), the
  // arrows move and wrap, Home and End jump, and Escape, Tab or a pick closes it with the focus back on its button
  const focusTo = useRef<'first' | 'last' | null>(null), inside = useRef<PopName | null>(null);
  useIsoLayoutEffect(() => {
    if (pop) { const to = focusTo.current, el = pops.current[pop]; focusTo.current = null; if (to && el) focusMenu(el, to); return; }
    if (inside.current) { const b = triggers.current[inside.current]; inside.current = null; b?.focus({ preventScroll: true }); }
  }, [pop]);
  useIsoLayoutEffect(() => {
    if (!pop) return;
    const btn = triggers.current[pop], el = pops.current[pop], host = box.current; if (!btn || !el || !host) return;
    // the mode sits near the right end of the bar, so its menu lines up with the button's right edge
    const hr = host.getBoundingClientRect(), br = btn.getBoundingClientRect(), end = pop === 'mode';
    let x = end ? br.right - hr.left - el.offsetWidth : br.left - hr.left;
    x = Math.max(-hr.left + 8, Math.min(x, innerWidth - hr.left - el.offsetWidth - 8));
    const up = br.bottom + el.offsetHeight + 12 > innerHeight && br.top - el.offsetHeight > 12;
    const top = up ? br.top - hr.top - el.offsetHeight - 6 : br.bottom - hr.top + 6;
    setPlace(p => ({ ...p, [pop]: { left: x, top, '--dm-origin': (up ? 'bottom ' : 'top ') + (end ? 'right' : 'left') } as CSSProperties }));
  }, [pop]);
  useEffect(() => {
    if (!pop) return;
    const click = (e: MouseEvent) => { const t = e.target as Node; if (!pops.current[pop]?.contains(t) && !triggers.current[pop]?.contains(t)) setPop(null); };
    const key = (e: KeyboardEvent) => {
      const el = pops.current[pop], t = e.target as Node;
      if (e.key === 'Escape') { if (el?.contains(t)) inside.current = pop; setPop(null); return; }
      if (e.defaultPrevented || !el || !el.contains(t)) return;
      if (e.key === 'Tab') { triggers.current[pop]?.focus({ preventScroll: true }); inside.current = null; setPop(null); return; }
      const to = menuStep(el, e.key); if (to) { e.preventDefault(); to.focus({ preventScroll: true }); }
    };
    const track = (e: FocusEvent) => { inside.current = pops.current[pop]?.contains(e.target as Node) ? pop : null; };
    const resize = (e: UIEvent) => { if (e.isTrusted) setPop(null); };
    document.addEventListener('focusin', track);
    document.addEventListener('click', click); document.addEventListener('keydown', key); addEventListener('resize', resize);
    return () => { document.removeEventListener('click', click); document.removeEventListener('keydown', key); document.removeEventListener('focusin', track); removeEventListener('resize', resize); };
  }, [pop]);
  const trigger = (name: PopName) => ({
    ref: (el: HTMLButtonElement | null) => { triggers.current[name] = el; },
    'aria-expanded': pop === name, 'aria-haspopup': 'menu' as const,
    onClick: (e: { detail: number }) => { if (pop !== name && e.detail === 0) focusTo.current = 'first'; setPop(p => p === name ? null : name); },
    onKeyDown: (e: { key: string; preventDefault: () => void }) => {
      if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return;
      e.preventDefault(); const where = e.key === 'ArrowUp' ? 'last' : 'first', el = pops.current[name];
      if (pop === name && el) focusMenu(el, where); else { focusTo.current = where; setPop(name); }
    }
  });
  const popProps = (name: PopName, cls: string) => ({
    ref: (el: HTMLDivElement | null) => { pops.current[name] = el; },
    className: cx('dm-pop dm-mx-pop dm-mx-rows dm-mx-glide', cls, pop === name && 'dm-open'), style: place[name], inert: pop !== name
  });

  /* ---------- attachments leave with a short fade before they go ---------- */
  const [leaving, setLeaving] = useState<string[]>([]);
  const latest = useRef(files);
  useEffect(() => { latest.current = files; });
  const remove = (key: string) => {
    setLeaving(l => [...l, key]);
    setTimeout(() => { setLeaving(l => l.filter(k => k !== key)); setFiles(latest.current.filter(f => f.key !== key)); }, 300);
  };

  /* ---------- dictation: what was there comes back on cancel ---------- */
  const before = useRef('');
  const wasDictating = useRef(dictating);
  useEffect(() => {
    if (dictating && !wasDictating.current) { before.current = text; setText(''); }
    wasDictating.current = dictating;
  }); // eslint-disable-line react-hooks/exhaustive-deps
  const endDictation = (keep: boolean) => { if (!keep) setText(before.current); onDictationEnd?.(keep); ta.current?.focus({ preventScroll: true }); };

  // send waits for text or a file, and for every file to finish loading
  const canSend = (!!text.trim() || files.length > 0) && !files.some(f => f.status === 'loading' || f.status === 'error');
  const submit = () => {
    if (!canSend || busy) return;
    onSubmit?.({ text: text.trim(), attachments: files });
    setText(''); setFiles([]);
  };

  return (
    // its motion (motion pieces): its menus grow out of their buttons, their rows settle one after another and one highlight
    // glides between them; presses show at once; icons crossfade and words that change ease their box to the new width; the
    // thread and the box grow on the spring
    <div data-dm="" ref={root} className={cx('dm-cpx dm-growing dm-mx-grow', className)}>
      <div ref={inner} className="dm-grow">
      <div className="dm-cpx-thread" aria-live="polite">{thread}</div>
      <div ref={box} className="dm-cpx-box" data-mode={dictating ? 'voice' : 'idle'}>
        <div className="dm-cpx-att dm-mx-ic">{files.map(f => (
          <span key={f.key} className={cx('dm-fchip', f.status === 'loading' && 'dm-ld', f.status === 'error' && 'dm-err', leaving.includes(f.key) ? 'dm-leave' : 'dm-enter')}>
            <span className="dm-ic" style={{ display: 'grid' }}><SwapIcon id={f.status ?? 'ready'}>{f.status === 'loading' ? <Spin /> : <Icon name={f.status === 'error' ? 'alert' : f.icon ?? 'clip'} size="xs" />}</SwapIcon></span>
            <Swap className="dm-n dm-mx-w">{f.label}</Swap>
            {f.status === 'error' && onRetry && <Tip label="Try again"><button type="button" className="dm-rt" aria-label="Try again" onClick={() => onRetry(f.key)}><Icon name="refresh" size="xs" /></button></Tip>}
            <button type="button" className="dm-x" aria-label={'Remove ' + f.label} onClick={() => remove(f.key)}><Icon name="x" size="xs" /></button>
          </span>))}
        </div>
        <textarea ref={ta} className="dm-cpx-ta" rows={1} aria-label="Message" placeholder={dictating ? 'Listening…' : placeholder} value={text}
          onChange={e => setText(e.target.value)}
          onKeyDown={e => {
            if (e.key === 'Enter' && !e.shiftKey && !dictating) { e.preventDefault(); submit(); }
            if (e.key === 'Escape' && dictating) endDictation(false);
          }} />
        <div className="dm-cpx-rows">
          <div className="dm-cpx-bar" inert={dictating}>
            <Tip label="Attach a file or a frame" off={pop === 'plus'}><button type="button" className="dm-ib dm-cpx-add dm-mx-press" aria-label="Attach" {...trigger('plus')}><Icon name="clip" /></button></Tip>
            {ctxOpt && <Tip label="What the agent works on" off={pop === 'ctx'}><button type="button" className="dm-chip dm-cpx-ctx dm-mx-ic" {...trigger('ctx')}><SwapIcon id={ctxOpt.value}><Icon name={ctxOpt.icon ?? 'folder'} /></SwapIcon><Swap className="dm-cpx-ctx-n dm-mx-w">{ctxOpt.label ?? ctxOpt.value}</Swap><Icon name="chev-d" size="xs" /></button></Tip>}
            <span className="dm-sp" />
            {tools}
            {mdOpt && <Tip label="What the agent may do" off={pop === 'mode'}><button type="button" className="dm-chip dm-cpx-mode dm-mx-ic" {...trigger('mode')}><SwapIcon id={mdOpt.value}><Icon name={mdOpt.icon ?? 'edit'} /></SwapIcon><Swap className="dm-cpx-mode-n dm-mx-w">{mdOpt.label ?? mdOpt.value}</Swap><Icon name="chev-d" size="xs" /></button></Tip>}
            {onDictate && <Tip label="Dictate"><button type="button" className="dm-ib dm-cpx-mic dm-mx-press" aria-label="Dictate" onClick={onDictate}><Icon name="mic" /></button></Tip>}
            {/* send and stop are one button, so its arrow and its square crossfade as the agent starts and stops */}
            <Tip label={busy ? 'Stop' : 'Send'} kbd={busy ? undefined : '↵'}><button type="button" className="dm-cpx-send dm-mx-ic" aria-label={busy ? 'Stop' : 'Send'} disabled={!busy && !canSend} onClick={busy ? onStop : submit}><SwapIcon id={busy ? 'stop' : 'up'}><Icon name={busy ? 'stop' : 'up'} /></SwapIcon></button></Tip>
          </div>
          <div className="dm-cpx-voice" inert={!dictating}>
            <span className="dm-cpx-rec"><span className="dm-cpx-dot" />Listening</span><span className="dm-cpx-tm dm-num dm-muted">{clock(dictationSeconds ?? counted)}</span>
            <span className="dm-sp" />
            <button type="button" className="dm-pill dm-ghost dm-sm dm-cpx-cancel dm-mx-press" onClick={() => endDictation(false)}>Cancel</button>
            <button type="button" className="dm-pill dm-primary dm-sm dm-cpx-ok" onClick={() => endDictation(true)}>Done</button>
          </div>
        </div>

        <div role="menu" aria-label="Attach" {...popProps('plus', 'dm-pp-plus')}>
          {addOptions.map(o => <button key={o.value} type="button" role="menuitem" className="dm-mi dm-mx-press" onClick={pick(() => onAdd?.(o.value))}><Icon name={o.icon ?? 'clip'} /><span>{o.label ?? o.value}{o.detail && <span className="dm-d">{o.detail}</span>}</span></button>)}
        </div>
        {contexts && contexts.length > 0 && <div role="menu" aria-label="Working on" {...popProps('ctx', 'dm-pp-ctx')}>
          <div className="dm-ph">Working on</div>
          {contexts.map(o => <button key={o.value} type="button" role="menuitemradio" aria-checked={o.value === ctx} className="dm-mi dm-mx-press" onClick={pick(() => setCtx(o.value))}><Icon name={o.icon ?? 'folder'} /><span>{o.label ?? o.value}{o.detail && <span className="dm-d">{o.detail}</span>}</span><Check /></button>)}
        </div>}
        <div role="menu" aria-label="The agent may" {...popProps('mode', 'dm-pp-mode')}>
          <div className="dm-ph">The agent may</div>
          {modes.map(o => <button key={o.value} type="button" role="menuitemradio" aria-checked={o.value === md} className="dm-mi dm-mx-press" onClick={pick(() => setMd(o.value))}><Icon name={o.icon ?? 'edit'} /><span>{o.label ?? o.value}{o.detail && <span className="dm-d">{o.detail}</span>}</span><Check /></button>)}
        </div>
      </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Composer ---------- */
.dm-cpx{display:flex;flex-direction:column;justify-content:flex-end;gap:14px;overflow-anchor:none;container-type:inline-size}
/* neither the composer nor the box it sits in anchors the page's scroll, so the page stays put as the thread grows and clears */
.dm-stage-in:has(>.dm-cpx){overflow-anchor:none}
/* no room is kept for the conversation (owner, 18 Nov): the thread and the box grow together (grow()) and stay centred in the
   stage. Its menus open over it from their buttons, down when there is room and up when there isn't, and the composer never
   moves for them (the visitor's clicks never move it). grow() must not clip the menus */
.dm-cpx.dm-growing{overflow:visible}
/* its motion (the core's motion pieces, owner, 26 Nov): its menus grow out of their buttons and go back quicker, their rows
   settle one after another and one highlight glides between them; a press shows at once (.mx-press, no scale); a chip's icon
   crossfades to the new pick and its box eases to the new words' width (.mx-w), as a file's name does when it can't be opened;
   a file's spinner crossfades to its icon; and the thread and the box grow on the spring (.mx-grow) */
.dm-cpx-thread{display:flex;flex-direction:column;gap:var(--dm-s-3)}
.dm-cpx-thread:empty{display:none}
/* a message is a small card: its files and words 16px from its edges */
.dm-cpx-thread .dm-bub{padding:var(--dm-s-4)}
/* a message that is only attachments (owner, 19 Nov): the files sit on their own at the thread's right edge, as a chat app shows
   them, never in an empty bubble; with words they stay in the bubble, above the words */
.dm-cpx-files{align-self:flex-end;max-width:85%;display:flex;flex-wrap:wrap;justify-content:flex-end;gap:6px}
.dm-cpx-ag{font-size:14px;color:var(--dm-fg2);display:flex;gap:var(--dm-s-2);align-items:center}
/* the composer is a component, not a field: a quiet hairline and a soft shadow, the same while you type in it */
.dm-cpx-box{position:relative;background:var(--dm-surface);border-radius:var(--dm-r-box);box-shadow:var(--dm-shadow);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dm-cpx-box{corner-shape:squircle;border-radius:var(--dm-r-box-sq)}}
/* everything in the box sits 16px from its edges (owner, 18 Nov): the attachments, the text, Send's edge and the dictation
   line; the attach button's glyph lines up with the text, and the toolbar's controls share one centre line */
.dm-cpx-att{display:flex;gap:6px;flex-wrap:wrap;padding:16px 16px 0}
.dm-cpx-att:empty{display:none}
.dm-cpx-att .dm-fchip{transition:color .32s,background .32s}
/* a chip never runs past the box on a narrow card: it shrinks to the row and its name trims */
.dm-cpx-att .dm-fchip{max-width:100%;min-width:0}
.dm-cpx-att .dm-fchip .dm-n{min-width:0;overflow:hidden;text-overflow:ellipsis}
.dm-cpx-att .dm-fchip .dm-x,.dm-cpx-att .dm-fchip .dm-rt{display:grid;place-items:center;width:18px;height:18px;border-radius:50%;margin-right:-4px;color:var(--dm-muted)}
@media (hover:hover) and (pointer:fine){.dm-cpx-att .dm-fchip .dm-x:hover,.dm-cpx-att .dm-fchip .dm-rt:hover{background:var(--dm-row);color:var(--dm-fg)}}
.dm-cpx-att .dm-fchip .dm-spin{width:10px;height:10px}
.dm-cpx-att .dm-fchip.dm-ld{color:var(--dm-muted)}
.dm-cpx-att .dm-fchip.dm-err{color:var(--dm-bad);background:var(--dm-bad-bg);box-shadow:none}
.dm-cpx-att .dm-fchip.dm-err .dm-rt{color:var(--dm-bad)}
.dm-cpx-ta{display:block;width:100%;border:0;outline:0;resize:none;background:none;color:var(--dm-fg);font:inherit;font-size:14px;line-height:1.5;padding:14px 16px var(--dm-s-1);min-height:54px;max-height:160px;transition:color .32s}
.dm-cpx-ta::placeholder{color:var(--dm-muted)}
.dm-cpx-box[data-mode="voice"] .dm-cpx-ta{color:var(--dm-fg2)}
.dm-cpx-rows{display:grid;padding:4px 16px 16px}
.dm-cpx-bar,.dm-cpx-voice{grid-area:1/1;display:flex;align-items:center;gap:var(--dm-s-1);min-width:0;transition:opacity .32s var(--dm-ease),transform .42s var(--dm-ease)}
.dm-cpx-voice{opacity:0;transform:translateY(6px);pointer-events:none;visibility:hidden;transition:opacity .32s var(--dm-ease),transform .42s var(--dm-ease),visibility 0s .32s}
.dm-cpx-box[data-mode="voice"] .dm-cpx-bar{opacity:0;transform:translateY(-6px);pointer-events:none}
.dm-cpx-box[data-mode="voice"] .dm-cpx-voice{opacity:1;transform:none;pointer-events:auto;visibility:visible;transition-delay:0s}
.dm-cpx-bar>.dm-ib{width:32px;height:32px;flex:none}
.dm-cpx-add[aria-expanded="true"]{background:var(--dm-chip);color:var(--dm-fg)}
.dm-cpx-bar .dm-chip{height:32px;padding:0 10px;gap:6px;background:none;min-width:0;font-size:13px;color:var(--dm-fg2)}
.dm-cpx-bar .dm-chip[aria-expanded="true"]{background:var(--dm-row);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.dm-cpx-bar .dm-chip:hover{background:var(--dm-row);color:var(--dm-fg)}}
.dm-cpx-bar .dm-chip>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-cpx-bar .dm-chip>svg:last-child{color:var(--dm-muted)}
/* a narrow box: the context and mode chips keep only their icon (the name stays for screen readers, and in the tooltip) */
/* (narrow, a chip shows only its icon and is a circle) */
@container (max-width:400px){.dm-cpx-bar .dm-chip{width:32px;padding:0;justify-content:center}.dm-cpx-bar .dm-chip>span{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.dm-cpx-bar .dm-chip>svg:last-child{display:none}}
.dm-cpx-send{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:var(--dm-accent);color:var(--dm-on-accent);flex:none;transition:opacity .32s,transform .16s,background .16s}
@media (hover:hover) and (pointer:fine){.dm-cpx-send:hover{background:var(--dm-accent-2)}}
.dm-cpx-send[disabled]{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring)}
/* dictation: a red dot and a clock while it listens, the words arriving in the box, then Cancel or Done */
.dm-cpx-rec{display:inline-flex;align-items:center;gap:var(--dm-s-2);font-size:13px;color:var(--dm-fg)}
.dm-cpx-dot{width:8px;height:8px;border-radius:50%;background:var(--dm-bad-mark);animation:dm-cpxrec 1.6s var(--dm-ease-io) infinite}
@keyframes dm-cpxrec{50%{opacity:.35}}
.dm-cpx-tm{font-size:13px;margin-left:var(--dm-s-1)}
.dm-cpx-voice .dm-pill{flex:none}
.dm-pp-plus,.dm-pp-ctx,.dm-pp-mode{width:264px}
.dm-cpx-bar>.dm-cpx-send{flex:none}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink Send alone presses */
